import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        String[][] ops = new String[(int) n][2];
        for (int i = 0; i < ops.length; i++) {
            for (int j = 0; j < ops[i].length; j++) {
                ops[i][j] = next();
            }
        }

        Deque<Long> queue = new ArrayDeque<>(), mx = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String op = ops[i][0];
            if (op.equals("enqueue")) {
                long x = Long.parseLong(ops[i][1]);
                queue.addLast(x);
                while (!mx.isEmpty() && mx.peekLast() < x) mx.pollLast();
                mx.addLast(x);
            } else if (op.equals("dequeue")) {
                long v = queue.pollFirst();
                if (mx.peekFirst() == v) mx.pollFirst();
                sb.append(v).append("\n");
            } else {
                sb.append(mx.peekFirst()).append("\n");
            }
        }
        System.out.print(sb);
    }
}
